-- Cassandra / ScyllaDB keyspace & query consistency pattern
CREATE KEYSPACE user_profiles WITH replication = {
  'class': 'NetworkTopologyStrategy',
  'us_east': 3,
  'eu_west': 3
};

-- Application session defaults:
-- Write CL = LOCAL_QUORUM (W=2 in local DC, async to remote DC)
-- Read  CL = LOCAL_QUORUM (R=2 in local DC -> W+R = 4 > 3)
-- Avoid ConsistencyLevel.ALL (any single-node restart causes outage)
